import itertools

def find_all_interval_series(n=6):
    solutions = []
    for perm in itertools.permutations(range(n)):
        diffs = [abs(perm[i+1] - perm[i]) for i in range(n-1)]
        if sorted(diffs) == list(range(1, n)):
            solutions.append((list(perm), diffs))
    return solutions

solutions = find_all_interval_series(6)
print(f"Found {len(solutions)} solutions:")
for perm, diffs in solutions:
    print(f"  {perm} -> diffs: {diffs}")
